const upsertCrewReport = `-- name: UpsertCrewReport :exec
insert into app.reports (reporter_id, reported_id, crew_id, reason, details, created_at, updated_at)
values ($1, $2, $3, $4, $5, $6, $6)
on conflict (reporter_id, reported_id, crew_id) where crew_id is not null do update
set reason = excluded.reason, details = excluded.details, updated_at = excluded.updated_at
`

type UpsertCrewReportParams struct {
	ReporterID pgtype.UUID
	ReportedID uuid.UUID
	CrewID     pgtype.UUID
	Reason     string
	Details    string
	At         pgtype.Timestamptz
}

func (q *Queries) UpsertCrewReport(ctx context.Context, arg UpsertCrewReportParams) error {
	_, err := q.db.Exec(ctx, upsertCrewReport,
		arg.ReporterID,
		arg.ReportedID,
		arg.CrewID,
		arg.Reason,
		arg.Details,
		arg.At,
	)
	return err
}
